/* BAIO Storybooks — alternative stories ("Story 2") and bonus books.
   Same page format as books-pu1.js. Extra fields: alt = id of the chapter's first story, star = cast shown on the cover,
   bonus = book without a chapter app (shown on the Bonus shelf). */
window.BOOKS = window.BOOKS || {};

/* ================= I PUC ================= */

BOOKS['pu1-ch5-b'] = { title:'The Seed’s Big Journey', ch:'I PUC · Ch 5 · Morphology of Flowering Plants', cover:'🌱', color:'#4f9a3a', page:'pu1-ch5.html', alt:'pu1-ch5', star:'Beeja the seed 🌱 & Buzz the bee 🐝',
 pages:[
  {t:'Waiting Under the Soil', bg:'field', e:'🌱🟤💤', x:'A tiny bean seed named Beeja lay under the soil, waiting for rain. "What am I made of?" she wondered. Outside was her [[seed coat]] with two layers — the outer [[testa]] and the inner [[tegmen]]. A scar called the [[hilum]] showed where she was once attached to the fruit, and a tiny pore, the [[micropyle]], sat just above it.', r:'A dicot seed has a seed coat, two fleshy cotyledons and an embryonal axis with a radicle and a plumule.'},
  {t:'The First Drink', bg:'river', e:'🌧️💧🌱', x:'One morning rain soaked the soil. Water rushed in through the micropyle and Beeja swelled up — [[germination]] had begun! Inside, two thick [[cotyledons]] fed the [[embryonal axis]]. Her neighbour, a maize grain, explained, "I am a monocot. My food is in the [[endosperm]], covered by a protein layer called the [[aleurone layer]]. My single cotyledon is the [[scutellum]]."', r:'Maize: plumule is covered by the coleoptile and radicle by the coleorhiza. Most monocot seeds are endospermic.'},
  {t:'Roots Go Down', bg:'forest', e:'⬇️🌱🪱', x:'First the [[radicle]] pushed downward and became the main root. Its branches formed a [[tap root system]], typical of dicots like mustard. The maize grain grew a bunch of thin roots instead — a [[fibrous root system]]. "Some roots even grow from stems," said an earthworm, pointing at a banyan tree whose [[prop roots]] hung down like pillars. These are [[adventitious roots]].', r:'Root regions from tip: root cap, region of meristematic activity, region of elongation and region of maturation (root hairs).'},
  {t:'The Shoot Rises', bg:'garden', e:'⬆️🌿☀️', x:'Now the [[plumule]] rose toward the sunlight and became the stem. Beeja’s stem had [[nodes]], where leaves are born, and [[internodes]] between them. Water climbed up through thin pipes called [[xylem]], while food travelled through [[phloem]]. A pumpkin vine waved its [[tendrils]] — "My stem is modified for climbing!" — and a citrus bush showed its sharp [[thorns]].', r:'Stem modifications: tendrils (cucumber, grapevine), thorns (Citrus, Bougainvillea), underground stems for storage (potato, ginger).'},
  {t:'Leaves Unfold', bg:'garden', e:'🍃🍃🌞', x:'Green leaves opened at each node. Each had a [[leaf base]], a stalk called the [[petiole]] and a flat [[lamina]]. Beeja’s veins formed a net — [[reticulate venation]] — while the maize leaf had straight lines: [[parallel venation]]. The leaves were arranged in a pattern called [[phyllotaxy]]: alternate in Beeja, opposite in guava, whorled in Alstonia.', r:'A simple leaf has an undivided lamina; a compound leaf has leaflets — pinnately compound (neem) or palmately compound (silk cotton).'},
  {t:'Time to Flower', bg:'garden', e:'🌸🌼🌺', x:'Weeks later Beeja grew buds. They were arranged on an axis — the [[inflorescence]]. In a [[racemose]] inflorescence the main axis keeps growing; in a [[cymose]] one it ends in a flower. Each flower had four whorls: [[calyx]], [[corolla]], [[androecium]] and [[gynoecium]]. Her ovary sat above the other parts, so she was [[hypogynous]].', r:'Perigynous: ovary half-inferior (plum, rose). Epigynous: ovary inferior (guava, cucumber, ray florets of sunflower).'},
  {t:'Calling the Pollinators', bg:'sky', e:'🐝🌸💛', x:'Bright petals and sweet scent called Buzz the bee. "Your petals overlap in a special way," buzzed Buzz — the [[vexillary]] aestivation of the pea family. He brushed against the [[stamens]], each made of a [[filament]] and an [[anther]], and carried pollen to the [[stigma]]. Inside the ovary, ovules sat on a ridge called the [[placenta]] — [[marginal placentation]].', r:'Types of placentation: marginal (pea), axile (china rose, tomato, lemon), parietal (mustard, Argemone), free central (Dianthus) and basal (sunflower).'},
  {t:'Seeds for Tomorrow', bg:'field', e:'🫛🌱✨', x:'After fertilisation the ovary became a [[fruit]] — a pod — and the ovules became new seeds. "A fruit formed without fertilisation is a [[parthenocarpic fruit]]," buzzed Buzz. Beeja belonged to the family [[Fabaceae]]: zygomorphic flowers, ten diadelphous stamens and a pod. As the pods dried and split, new Beejas fell to the soil, ready for their own big journey.', r:'Floral formula of Fabaceae: % ⚥ K(5) C1+2+(2) A(9)+1 G1. Members: pea, soybean, groundnut, gram.'}],
 quiz:[['What is germination?',['Formation of flowers','Growth of the embryo into a seedling','Fusion of gametes','Falling of leaves'],1],['Which tissue transports water in plants?',['Phloem','Xylem','Cortex','Epidermis'],1],['What is the main function of a flower?',['Photosynthesis','Storage of food','Sexual reproduction','Absorbing water'],2],['A tap root develops from the:',['Plumule','Radicle','Cotyledon','Stem node'],1],['After fertilisation the ovary develops into the:',['Seed','Fruit','Embryo','Endosperm'],1]]};

BOOKS['pu1-ch8-b'] = { title:'The Missing Powerhouse', ch:'I PUC · Ch 8 · Cell: The Unit of Life', cover:'🌻', color:'#e0952a', page:'pu1-ch8.html', alt:'pu1-ch8', star:'Maya 👧 & Professor Nucleus 🔬',
 pages:[
  {t:'Maya’s Drooping Sunflower', bg:'garden', e:'🌻👧💧', x:'Maya’s sunflower had water, sunlight and good soil — yet its leaves were pale and weak. Suddenly a tiny scientist in a purple coat landed on a leaf. "I am Professor Nucleus! Every living thing is made of cells — that is the [[cell theory]] of [[Schleiden]] and [[Schwann]]. And as [[Virchow]] said, all cells come from pre-existing cells. Let’s go inside and find the problem!"', r:'Cell theory: all living organisms are composed of cells and products of cells; all cells arise from pre-existing cells.'},
  {t:'Through the Wall', bg:'cell', e:'🧱🔬👧', x:'They shrank and reached a strong green wall. "This is the [[cell wall]]," said the professor. "Made of [[cellulose]], hemicellulose, pectins and proteins." Between two cells lay a sticky layer of calcium pectate — the [[middle lamella]]. Tiny tunnels called [[plasmodesmata]] crossed the walls, joining the cytoplasm of neighbouring cells. Maya’s first task: name it! The cell glowed a little brighter.', r:'The primary wall of a young cell can grow; the secondary wall forms later on its inner side.'},
  {t:'The Selective Gatekeeper', bg:'cell', e:'🚪🔵🟡', x:'Next came a soft, moving gate — the [[plasma membrane]]. "It is a [[lipid bilayer]] with proteins floating in it," explained the professor. "Singer and Nicolson called it the [[fluid mosaic model]] (1972)." Water slipped through by [[osmosis]], while some ions were pumped in using energy — [[active transport]]. "It is [[selectively permeable]]," Maya said proudly. Another light switched on!', r:'Passive transport needs no energy (diffusion, osmosis); active transport uses ATP, e.g. the Na⁺/K⁺ pump.'},
  {t:'The Jelly Sea', bg:'cell', e:'🌊🟣⚙️', x:'Inside, they floated in a jelly-like [[cytoplasm]], the site of many reactions. Granules called [[ribosomes]] were busy making proteins. A maze of tubes — the [[endoplasmic reticulum]] — ran through the cell: [[rough ER]] studded with ribosomes, and [[smooth ER]] that makes lipids. Stacks of flat sacs, the [[Golgi apparatus]], packed products into little bubbles.', r:'Eukaryotic ribosomes are 80S (60S + 40S). Golgi is the site of glycoprotein and glycolipid formation.'},
  {t:'The Control Room', bg:'cell', e:'🟣🧬🎛️', x:'A giant purple sphere loomed ahead. "My home — the [[nucleus]], first seen by [[Robert Brown]]!" It had a double [[nuclear envelope]] with [[nuclear pores]]. Inside, thread-like [[chromatin]] carried DNA, and a dense [[nucleolus]] made ribosomal RNA. "The nucleus controls every activity of the cell," said Maya. "Correct!" The control room lights blinked on.', r:'Mammalian red blood cells and sieve tube cells of plants have no nucleus.'},
  {t:'Kitchens and a Water Tank', bg:'cell', e:'🟢🫙💧', x:'Green discs drifted past — [[chloroplasts]]. Stacks of [[thylakoids]] called [[grana]] trapped sunlight, and the fluid [[stroma]] held enzymes for making sugar. In the centre lay a huge water tank, the [[vacuole]], wrapped in a membrane called the [[tonoplast]]. "In plant cells it can fill up to 90 percent of the volume," the professor said.', r:'Plastids: chloroplasts (green), chromoplasts (yellow-orange-red carotenoids) and leucoplasts (colourless stores).'},
  {t:'The Silent Powerhouse', bg:'cell', e:'🔋⚡😟', x:'Finally they found the problem: sausage-shaped [[mitochondria]] lying silent. "These are the powerhouses — sites of [[aerobic respiration]] that make [[ATP]]," said the professor. Maya studied one: an outer membrane, an inner membrane folded into [[cristae]], and a [[matrix]] with its own circular DNA and 70S ribosomes. As she named each part, the cristae began to hum.', r:'Mitochondria are semi-autonomous: they have their own DNA and ribosomes and divide by fission.'},
  {t:'The Sunflower Stands Tall', bg:'garden', e:'🌻☀️🎉', x:'With every organelle named, the mitochondria roared back to life and ATP flowed through the cell like electricity. Back outside, Maya watched her sunflower lift its head toward the sun, its leaves deep green again. "Remember," said Professor Nucleus, "a cell is not just a bag — it is a city where every part has a job." And with a wink, he flew away.', r:'Prokaryotic cells lack a nuclear membrane and membrane-bound organelles; eukaryotic cells have both.'}],
 quiz:[['Which organelle is called the powerhouse of the cell?',['Ribosome','Mitochondrion','Golgi apparatus','Lysosome'],1],['Which organelle controls the activities of the cell?',['Vacuole','Nucleus','Chloroplast','Cell wall'],1],['Which structure controls what enters and leaves the cell?',['Cell wall','Plasma membrane','Nucleolus','Cytoplasm'],1],['The fluid mosaic model was proposed by:',['Watson and Crick','Singer and Nicolson','Schleiden and Schwann','Robert Brown'],1],['The membrane around the plant vacuole is the:',['Tonoplast','Middle lamella','Nuclear envelope','Cristae'],0]]};

/* ================= II PUC ================= */

BOOKS['pu2-ch4-b'] = { title:'The Secret Family Tree', ch:'II PUC · Ch 4 · Principles of Inheritance and Variation', cover:'🕵️‍♀️', color:'#3a8f8a', page:'pu2-ch4.html', alt:'pu2-ch4', star:'Detective Ria 🕵️‍♀️ & Dr. Gene 🧬',
 pages:[
  {t:'The Old Family Album', bg:'city', e:'📸🕵️‍♀️❓', x:'Detective Ria found an old album with photographs of four generations. Grandpa had dimples, Mother had none, but baby cousin Anu did! Great-grandma had attached earlobes, nobody in the next two generations did — and then Ria’s brother did. "Why do traits skip generations?" she asked. Her friend Dr. Gene smiled. "The answer is [[inheritance]] — and it begins with a monk and his peas."', r:'Inheritance is the process by which characters pass from parent to progeny; variation is the degree of difference between them.'},
  {t:'Mendel’s Pea Garden', bg:'garden', e:'🫛👨‍🌾📒', x:'Between 1856 and 1863, [[Gregor Mendel]] crossed garden peas and counted thousands of plants. He chose seven pairs of [[contrasting traits]] such as tall and dwarf, and used [[true-breeding]] lines. "Mendel called the hidden units ‘factors’ — today we call them [[genes]]," said Dr. Gene. "Different forms of the same gene are [[alleles]]: T for tall, t for dwarf."', r:'Mendel used statistical analysis and large samples, which made his conclusions reliable.'},
  {t:'Dominant and Recessive', bg:'lab', e:'🔠🔡⚖️', x:'"When Mendel crossed tall TT with dwarf tt, all the F₁ plants were tall," Dr. Gene explained. "T is [[dominant]]; t is [[recessive]] — it hides in the presence of T." TT and tt are [[homozygous]]; Tt is [[heterozygous]]. Ria wrote: the letters are the [[genotype]]; what we see — tall or dwarf — is the [[phenotype]].', r:'A recessive trait appears only in the homozygous (tt) condition.'},
  {t:'The Punnett Square', bg:'lab', e:'🟦🟩🧮', x:'Dr. Gene drew a grid named after [[Reginald Punnett]]. For Tt × Tt, the gametes T and t met in four boxes: TT, Tt, Tt and tt. "Phenotypic ratio 3 tall : 1 dwarf, genotypic ratio [[1:2:1]]," Ria counted. "So if both parents are Aa, the chance of an aa child is one in four — 25 percent!" The [[Punnett square]] had cracked the first clue.', r:'Law of Segregation: the two alleles of a gene separate during gamete formation, so each gamete gets only one.'},
  {t:'The Test Cross', bg:'lab', e:'🧪🌿❔', x:'"But a tall plant could be TT or Tt. How do we know?" asked Ria. "Cross it with a dwarf tt plant — a [[test cross]]," said Dr. Gene. "All tall offspring means TT; half tall and half dwarf means Tt." In a dihybrid cross of seed colour and shape, Mendel got a 9:3:3:1 ratio, showing the [[Law of Independent Assortment]].', r:'Mendel’s laws: Law of Dominance, Law of Segregation and Law of Independent Assortment.'},
  {t:'Beyond Mendel', bg:'garden', e:'🌸🩸🔀', x:'In the snapdragon, red RR × white rr gave pink Rr flowers — [[incomplete dominance]], with a 1:2:1 phenotypic ratio. Ria’s blood group was AB: "Both I^A and I^B show together — [[codominance]]!" And because the ABO gene has three alleles, it is also an example of [[multiple alleles]]. One gene can even affect many traits — [[pleiotropy]], as in phenylketonuria.', r:'ABO blood groups: alleles I^A, I^B and i give six genotypes and four phenotypes (A, B, AB, O).'},
  {t:'Reading the Pedigree', bg:'city', e:'🌳🔲⚫', x:'Ria drew the family as a [[pedigree chart]]: squares for males, circles for females, shaded for those with attached earlobes. "Look — two unaffected parents had an affected child. That is an [[autosomal recessive]] pattern," said Dr. Gene. "The same pattern is seen in [[sickle-cell anaemia]]. Traits on the X chromosome, like [[haemophilia]] and colour blindness, are [[sex-linked]]."', r:'Sickle-cell anaemia: Glu is replaced by Val at the 6th position of the β-globin chain (GAG → GUG).'},
  {t:'Mystery Solved', bg:'night', e:'💡🕵️‍♀️🎉', x:'Ria closed the album. "Great-grandma was aa. Grandma and Grandpa were both [[carriers]] — Aa — so their children showed the dominant free earlobe. When two carriers had children again, one in four was aa. The trait never vanished; it was hiding!" Dr. Gene clapped. "That is why recessive traits skip generations. Case closed, Detective!"', r:'Carriers are heterozygous individuals who do not show a recessive trait but can pass it on.'}],
 quiz:[['What is the difference between genotype and phenotype?',['They are the same','Genotype = genes; phenotype = visible trait','Phenotype = genes; genotype = trait','Genotype is only in plants'],1],['If both parents are Aa, what is the chance of an aa child?',['0%','25%','50%','100%'],1],['What is an allele?',['A type of chromosome','An alternative form of a gene','A cell organelle','A kind of mutation'],1],['ABO blood groups show:',['Incomplete dominance only','Codominance and multiple alleles','Complete dominance only','Pleiotropy only'],1],['A test cross is a cross with a:',['Homozygous dominant parent','Homozygous recessive parent','Heterozygous parent','Wild plant'],1]]};

BOOKS['pu2-ch5-b'] = { title:'The Message from the Nucleus', ch:'II PUC · Ch 5 · Molecular Basis of Inheritance', cover:'✉️', color:'#5b7fe0', page:'pu2-ch5.html', alt:'pu2-ch5', star:'DNA the Librarian 📜 & mRNA the Messenger ✉️',
 pages:[
  {t:'A Secret Instruction', bg:'cell', e:'📜🔒🟣', x:'Deep inside a stomach cell, DNA the Librarian guarded a secret instruction: "Make an enzyme to digest food." But DNA can never leave the [[nucleus]]. "I will send a messenger," it said. This flow of information — DNA to RNA to protein — is the [[central dogma]], proposed by [[Francis Crick]]. "Let’s follow the message!"', r:'Central dogma: DNA → (transcription) → RNA → (translation) → protein. In some viruses RNA → DNA by reverse transcription.'},
  {t:'The Twisted Ladder', bg:'lab', e:'🧬🔗🪜', x:'DNA was a [[double helix]], described by [[Watson and Crick]] in 1953. Its two strands run in opposite directions — [[antiparallel]]. "My base-pairing rules never change," said DNA. "[[Adenine]] pairs with [[thymine]] using two hydrogen bonds; [[guanine]] pairs with [[cytosine]] using three." One full turn of the helix is 3.4 nm long and has about 10 base pairs.', r:'Chargaff’s rule: in double-stranded DNA, A = T and G = C, so purines = pyrimidines.'},
  {t:'Copying the Message', bg:'cell', e:'✍️📃🟡', x:'The enzyme [[RNA polymerase]] arrived at a [[promoter]] and unzipped a short stretch of DNA. Reading the [[template strand]] (3′→5′), it built an RNA copy that matched the [[coding strand]] — except that [[uracil]] replaced thymine. At the [[terminator]] it stopped. This copying of DNA into RNA is called [[transcription]].', r:'A transcription unit has a promoter, a structural gene and a terminator.'},
  {t:'Editing the Draft', bg:'cell', e:'✂️📄🧢', x:'In eukaryotes the first copy, [[hnRNA]], is a rough draft. "Cut out the non-coding [[introns]] and join the coding [[exons]]," ordered the editor — this is [[splicing]]. Then a methyl guanosine triphosphate cap was added at the 5′ end — [[capping]] — and a long chain of adenylate residues at the 3′ end — [[tailing]]. Now the [[mRNA]] was ready to travel.', r:'Bacteria have no splicing; their mRNA can be translated even while it is being transcribed.'},
  {t:'Journey to the Ribosome', bg:'city', e:'✉️🚪🏭', x:'mRNA slipped out through a [[nuclear pore]] and reached the protein factory, the [[ribosome]]. The message was written in three-letter words called [[codons]] — the [[genetic code]]. Of 64 codons, 61 code for amino acids. [[AUG]] means "start" (methionine); UAA, UAG and UGA mean "stop". The code is [[degenerate]] — many codons can name one amino acid — and nearly [[universal]].', r:'George Gamow suggested a triplet code; Nirenberg and Khorana helped decode it.'},
  {t:'Building the Protein', bg:'lab', e:'🧱🔗🚚', x:'Delivery trucks called [[tRNA]] brought amino acids. Each tRNA had an [[anticodon]] that matched a codon on mRNA. First the amino acids were loaded — [[charging of tRNA]] (aminoacylation). Then came [[translation]]: initiation at AUG, elongation as [[peptide bonds]] formed, and termination when a release factor met a stop codon.', r:'In bacteria, 23S rRNA acts as a ribozyme that catalyses peptide bond formation.'},
  {t:'Switching Genes On and Off', bg:'field', e:'💡🔛🥛', x:'"A cell does not make every protein all the time," said DNA. In bacteria, [[Jacob and Monod]] discovered the [[lac operon]]. A [[repressor]] normally blocks the operator. When lactose arrives it acts as an [[inducer]], removes the repressor and switches on the genes for digesting lactose. This is [[gene regulation]].', r:'The lac operon has the structural genes z (β-galactosidase), y (permease) and a (transacetylase).'},
  {t:'The Enzyme Is Ready', bg:'cell', e:'🧪✅🍽️', x:'The new chain of amino acids folded into a working enzyme and set off to digest food. "The message reached the factory!" cheered mRNA. DNA smiled from its library. "Remember: the order of bases in DNA decides the order of amino acids in a protein — and the protein decides the trait."', r:'The Human Genome Project found about 3 × 10⁹ base pairs and about 20,000 genes in humans.'}],
 quiz:[['Which molecule carries the genetic message from the nucleus to the ribosome?',['tRNA','mRNA','rRNA','DNA'],1],['What are the base-pairing rules in DNA?',['A–G and T–C','A–T and G–C','A–U and G–C','A–C and G–T'],1],['What is the function of ribosomes?',['Making lipids','Protein synthesis','Storing water','Cell division'],1],['The start codon is:',['UAA','AUG','UGA','UAG'],1],['Splicing removes the:',['Exons','Introns','Cap','Poly-A tail'],1]]};

BOOKS['pu2-ch6-b'] = { title:'The Island of Change', ch:'II PUC · Ch 6 · Evolution', cover:'🏝️', color:'#c0843a', page:'pu2-ch6.html', alt:'pu2-ch6', star:'Tara 👧 & the island finches 🐦',
 pages:[
  {t:'Blown Away by a Storm', bg:'sea', e:'🌪️🐦🏝️', x:'A wild storm blew a small flock of seed-eating birds across the sea to a distant island. Tara, a young naturalist, watched them land. "This reminds me of [[Charles Darwin]]," she wrote. "On his voyage aboard [[HMS Beagle]], he saw small black birds on the [[Galapagos Islands]] — now called [[Darwin’s finches]]."', r:'Darwin’s finches show adaptive radiation: from one seed-eating ancestor arose many forms with different beaks.'},
  {t:'No Two Birds Alike', bg:'forest', e:'🐦🔍📏', x:'Tara measured every beak. Some were short, some long, some thick. "This is [[variation]]," she noted. "Some of it is inherited." Darwin said small variations add up over time. Later [[Hugo de Vries]], studying evening primrose, said large sudden changes — [[mutations]] — can also create new forms in a single step; he called it [[saltation]].', r:'Darwin: evolution is gradual. De Vries: mutations are random and directionless, causing speciation.'},
  {t:'The Seeds Get Harder', bg:'desert', e:'🌰💪🐦', x:'Years of dry weather left only large, hard seeds. Birds with thick, strong beaks cracked them easily and raised more chicks; weak-beaked birds struggled. "Nature is choosing," Tara wrote — [[natural selection]]. "The winners are not the strongest fighters but those that leave more offspring. That is [[fitness]] — reproductive fitness." Darwin called it [[survival of the fittest]].', r:'Natural selection acts on heritable variation; traits that increase reproductive success become more common.'},
  {t:'A Notebook of Generations', bg:'lab', e:'📒📈🐣', x:'Tara recorded beak sizes for ten generations. The average beak got thicker and thicker. "A feature that helps an organism survive and reproduce in its home is an [[adaptation]]," she wrote. Over time, birds on different parts of the island adapted to different foods — insects, cactus, seeds — showing [[adaptive radiation]], just like [[Australian marsupials]].', r:'Adaptive radiation: evolution of different species from one ancestor, radiating into different habitats.'},
  {t:'Clues in Bones and Wings', bg:'city', e:'🦴🦋🐦', x:'At the island museum Tara compared skeletons. The forelimbs of a whale, a bat, a cheetah and a human had the same bones but different jobs — [[homologous organs]], showing [[divergent evolution]]. The wings of a butterfly and a bird did the same job but had different structures — [[analogous organs]], showing [[convergent evolution]].', r:'Industrial melanism: in polluted England, dark moths (Biston betularia) increased because they were hidden on soot-covered trees.'},
  {t:'Counting Alleles', bg:'lab', e:'🧮🧬⚖️', x:'"If nothing disturbs a population, allele frequencies stay constant," Tara read. That is the [[Hardy-Weinberg principle]]: p² + 2pq + q² = 1. Five factors upset this balance: [[gene migration]], [[genetic drift]], mutation, recombination and natural selection. "Our flock is a tiny group that started a new population — a [[founder effect]]!"', r:'Genetic drift is a change in allele frequency by chance; it has a big effect in small populations.'},
  {t:'Three Ways to Select', bg:'sky', e:'📊↔️➡️', x:'Tara drew three graphs of beak size. When average beaks are favoured, it is [[stabilising selection]]. When one extreme is favoured — like thick beaks during the drought — it is [[directional selection]]. When both extremes do well and the middle loses, it is [[disruptive selection]]. "Our island showed directional selection," she concluded.', r:'Disruptive selection can split one population into two, leading to new species.'},
  {t:'A New Island Home', bg:'sea', e:'🏝️🐦🌅', x:'Many generations later, the island birds looked different from their mainland cousins and could no longer interbreed with them. A new species had formed — [[speciation]]. Tara closed her notebook. "Helpful traits become common because the birds that carry them leave more young. Evolution is not a plan — it is nature’s long, patient editing."', r:'Life on Earth: first cellular forms appeared about 2000 million years ago; Homo sapiens arose in Africa about 75,000–10,000 years ago.'}],
 quiz:[['What is natural selection?',['Humans choosing mates','Survival and reproduction of the best-suited','Random breeding','Humans making genes'],1],['What is an adaptation?',['A disease','A trait that aids survival','A fossil','A storm'],1],['Why do helpful traits spread over generations?',['Organisms choose them','Their carriers leave more young','They are learned','Nothing changes'],1],['The founder effect is an example of:',['Gene migration','Genetic drift','Mutation','Convergent evolution'],1],['Homologous organs indicate:',['Convergent evolution','Divergent evolution','No evolution','Industrial melanism'],1]]};

BOOKS['pu2-ch7-b'] = { title:'Defenders of the Body', ch:'II PUC · Ch 7 · Human Health and Disease', cover:'🦸', color:'#d0584e', page:'pu2-ch7.html', alt:'pu2-ch7', star:'Captain WBC 🦸 & the Immune Squad',
 pages:[
  {t:'An Intruder Sneaks In', bg:'city', e:'🦠👃🚨', x:'A tiny virus slipped into the body through the nose. Alarm signals spread through the bloodstream. "Intruder alert!" shouted Captain WBC, leader of the Immune Squad. "Any organism that causes disease is a [[pathogen]] — bacteria, viruses, fungi, protozoans or worms. Our job is [[immunity]]: the body’s power to fight them."', r:'Common cold is caused by rhinoviruses; it infects the nose and respiratory passage but not the lungs.'},
  {t:'The Walls and Gates', bg:'city', e:'🧱🧴😢', x:'The first defence was always ready — [[innate immunity]], present from birth and non-specific. The skin was a [[physical barrier]], and [[mucus]] in the nose trapped the virus. Acid in the stomach, saliva and tears were [[physiological barriers]]. "Not everyone gets stopped at the gate," the Captain admitted, "so the guards come next."', r:'Innate immunity has four barriers: physical, physiological, cellular and cytokine barriers.'},
  {t:'The Guards Attack', bg:'cell', e:'⚪⚔️🦠', x:'Guards rushed in: [[neutrophils]] (PMNL), [[monocytes]] and [[natural killer cells]], with [[macrophages]] swallowing invaders whole — the [[cellular barriers]]. Virus-infected cells sent out warning proteins called [[interferons]], which protect nearby healthy cells — the [[cytokine barrier]]. The area grew warm and swollen — inflammation, the sign of a battle.', r:'Interferons are proteins secreted by virus-infected cells that protect non-infected cells from further infection.'},
  {t:'The Special Forces', bg:'lab', e:'🎯🅱️🆃', x:'The virus kept multiplying, so the Captain called the special forces — [[acquired immunity]], which is specific and has [[memory]]. Two teams were trained: [[B-lymphocytes]] and [[T-lymphocytes]]. "Our first meeting with this virus gives a slow [[primary response]]," said the Captain. "Next time it will be fast and strong — the [[secondary response]], also called the anamnestic response."', r:'B and T lymphocytes are produced in the bone marrow; T cells mature in the thymus.'},
  {t:'Antibodies Lock On', bg:'cell', e:'🔒🧷🦠', x:'B-cells released Y-shaped proteins called [[antibodies]], each made of two heavy and two light chains — H₂L₂. Each antibody recognised one specific [[antigen]] on the virus and locked onto it. This is the [[humoral immune response]], as antibodies travel in the blood. Meanwhile T-cells attacked infected cells directly — the [[cell-mediated immunity]] that also causes graft rejection.', r:'Types of antibodies: IgA, IgM, IgE, IgG and IgD.'},
  {t:'Active and Passive', bg:'garden', e:'💉🍼🐍', x:'"When the body makes its own antibodies, it is [[active immunity]]," said the Captain. "When ready-made antibodies are given, it is [[passive immunity]] — like the [[colostrum]] in a mother’s first milk, rich in IgA, or the antivenom given after a snakebite." [[Vaccination]] gives weakened or inactivated germs so the body makes [[memory cells]] without falling ill.', r:'Recombinant DNA technology produces vaccines in bacteria or yeast, e.g. the hepatitis B vaccine from yeast.'},
  {t:'When Defenders Misfire', bg:'night', e:'🤧🌼⚠️', x:'Sometimes the squad overreacts. Harmless pollen or dust can trigger an [[allergy]]: [[IgE]] antibodies make [[mast cells]] release [[histamine]] and serotonin, causing sneezing and watery eyes. Sometimes the squad even attacks the body’s own cells — [[autoimmunity]], as in rheumatoid arthritis. The squad trains in [[primary lymphoid organs]] (bone marrow, thymus) and gathers in [[secondary lymphoid organs]] like the spleen and lymph nodes.', r:'MALT (mucosa-associated lymphoid tissue) makes up about 50 percent of the lymphoid tissue in the human body.'},
  {t:'Memory Cells Remember', bg:'sky', e:'🧠🦸🏆', x:'The virus was finally defeated. But a few [[memory cells]] stayed behind, holding the virus’s ‘photograph’. Months later the same virus returned — and was destroyed within hours, before any sneezing began. "That is why vaccines are so useful," said Captain WBC. "They train us before the real battle."', r:'Immunisation programmes have eradicated smallpox and nearly eliminated polio.'}],
 quiz:[['Which cells help fight infection?',['Red blood cells','White blood cells','Platelets','Nerve cells'],1],['What is the role of antibodies?',['To carry oxygen','To recognise and bind specific antigens','To digest food','To clot blood'],1],['Why are vaccines useful?',['They kill all bacteria','They produce memory cells for faster protection','They replace white blood cells','They cure allergies'],1],['Antibodies are produced by:',['T-lymphocytes','B-lymphocytes','Neutrophils','Red blood cells'],1],['Colostrum gives the baby:',['Active immunity','Passive immunity','Autoimmunity','No immunity'],1]]};

BOOKS['pu2-ch8-b'] = { title:'The Invisible World', ch:'II PUC · Ch 8 · Microbes in Human Welfare', cover:'🔬', color:'#3a9e86', page:'pu2-ch8.html', alt:'pu2-ch8', star:'Neha 👧 & Arjun 👦 — shrunk!',
 pages:[
  {t:'Shrinking Down', bg:'lab', e:'🔬👧👦', x:'Neha and Arjun pressed the button on an old microscope — and shrank! They found themselves in a hidden world full of [[bacteria]], [[fungi]], [[protozoa]] and [[viruses]], and even tinier [[viroids]] and [[prions]]. "These are [[microbes]]," boomed a voice. "Some cause disease, but most are helpers. Let us show you."', r:'Microbes are present everywhere — soil, water, air, inside our bodies and even in hot springs and deep under the soil.'},
  {t:'The Kitchen Helpers', bg:'garden', e:'🥛🍞🧀', x:'In a bowl of milk, rod-shaped [[Lactobacillus]] were turning it into curd. "We are [[lactic acid bacteria]] (LAB). We also raise vitamin B₁₂ in curd and fight harmful germs in your stomach." Nearby, [[baker’s yeast]] — Saccharomyces cerevisiae — puffed up bread dough. In a cheese shop, [[Propionibacterium sharmanii]] blew the big holes in Swiss cheese.', r:'The puffed-up appearance of dosa and idli dough is due to fermentation by bacteria.'},
  {t:'The Factory Floor', bg:'city', e:'🏭🍷💊', x:'At a factory, yeast made wine and beer without distillation, and whisky and rum with distillation. In a lab, they met [[Alexander Fleming]]’s famous mould — [[Penicillium notatum]] — which killed Staphylococci. "This was the first [[antibiotic]], [[penicillin]]," said Arjun. Chain and Florey later proved how well it worked.', r:'Acids from microbes: citric acid (Aspergillus niger), acetic acid (Acetobacter aceti), butyric acid (Clostridium butylicum), lactic acid (Lactobacillus).'},
  {t:'Medicines and Enzymes', bg:'lab', e:'🧪❤️🍊', x:'Bottles lined the shelves. "[[Streptokinase]] from Streptococcus is a clot buster for heart-attack patients," read Neha. "[[Cyclosporin A]] from Trichoderma polysporum stops organ rejection, and [[statins]] from the yeast Monascus purpureus lower blood cholesterol." [[Lipases]] in detergents remove oily stains; [[pectinases]] and proteases make bottled juices clear.', r:'Bioactive molecules from microbes are used as medicines, enzymes and food additives.'},
  {t:'Cleaning Dirty Water', bg:'river', e:'🚰🌀🫧', x:'They floated into a [[sewage treatment plant]]. In [[primary treatment]], grit and floating solids were removed physically. In [[secondary treatment]], air was pumped in and microbes grew into masses called [[flocs]], eating up the organic matter and lowering the [[BOD]]. The settled [[activated sludge]] went into [[anaerobic sludge digesters]].', r:'BOD (biochemical oxygen demand) measures organic matter in water; the higher the BOD, the more polluted the water.'},
  {t:'Gas from Cow Dung', bg:'field', e:'🐄🔥🏠', x:'In the sludge digesters and in a village gobar gas plant, the [[methanogens]] were at work — bacteria like [[Methanobacterium]] that also live in the rumen of cattle. They produced [[biogas]]: mainly methane with CO₂ and H₂. "It cooks food and lights homes," said a farmer. The technology was developed in India by IARI and KVIC.', r:'Cow dung is rich in methanogens, so it is the main raw material of biogas plants.'},
  {t:'Farmers’ Tiny Friends', bg:'field', e:'🐞🌾🍄', x:'In a field, ladybirds ate aphids — [[biocontrol]]. Spores of [[Bacillus thuringiensis]] (Bt) killed caterpillars, the fungus [[Trichoderma]] protected roots, and [[baculoviruses]] attacked only insects. Underground, [[Rhizobium]] fixed nitrogen in legume root nodules, [[mycorrhiza]] fungi like Glomus helped absorb phosphorus, and cyanobacteria like [[Anabaena]] fed rice paddies. These are [[biofertilisers]].', r:'Free-living nitrogen fixers in soil: Azotobacter and Azospirillum.'},
  {t:'Friends and Foes', bg:'garden', e:'🧼🤒🌍', x:'The microscope beeped and the children grew back to normal size. "Not all microbes are friends," Neha said, remembering Salmonella that causes typhoid. "That is why we wash our hands — to remove harmful germs. And viruses are different from bacteria: they are not cells and can multiply only inside a host." Arjun nodded. "But without microbes, there would be no curd, no medicines — and no recycling of nutrients on Earth."', r:'Decomposer microbes break down dead matter and return nutrients to the soil.'}],
 quiz:[['Name one useful microorganism.',['Plasmodium','Lactobacillus','HIV','Salmonella'],1],['How do bacteria differ from viruses?',['Bacteria are cells; viruses are not cells and need a host to multiply','Viruses are bigger','Bacteria cannot reproduce','There is no difference'],0],['Why should we wash our hands?',['To make them dry','To remove harmful germs','To get vitamins','To grow microbes'],1],['Penicillin was discovered by:',['Louis Pasteur','Alexander Fleming','Robert Koch','Edward Jenner'],1],['Biogas is produced by:',['Lactobacillus','Methanogens','Rhizobium','Yeast'],1]]};

BOOKS['pu2-ch12-b'] = { title:'The Broken Food Web', ch:'II PUC · Ch 12 · Ecosystem', cover:'🐸', color:'#2f8f6a', page:'pu2-ch12.html', alt:'pu2-ch12', star:'Kiran 👦 & the Pond Guardians 🐸',
 pages:[
  {t:'Where Did the Frogs Go?', bg:'pond', e:'🐸❓💧', x:'In a peaceful village pond, the frogs suddenly disappeared. Soon insects swarmed everywhere, water plants were eaten faster, fish found less food and the pond turned murky. Kiran and his friends, the Pond Guardians, decided to become ecosystem engineers. "First," said Kiran, "we must understand our [[ecosystem]] — living things and their surroundings working as one unit."', r:'An ecosystem has biotic components (producers, consumers, decomposers) and abiotic components (light, water, soil, temperature).'},
  {t:'The Food Makers', bg:'pond', e:'🌿🟢☀️', x:'They began with the green life: tiny [[phytoplankton]], algae and floating and rooted plants. "These are [[producers]] — they make food by photosynthesis," said Kiran. The rate at which they make biomass is [[productivity]]. Total food made is [[gross primary productivity]] (GPP); what remains after respiration is [[net primary productivity]] (NPP).', r:'NPP = GPP − R (respiration losses). NPP is the biomass available to consumers.'},
  {t:'Who Eats Whom?', bg:'pond', e:'🦗🐸🐍', x:'Next came the eaters, or [[consumers]]. Insects and zooplankton ate plants — [[primary consumers]]. Frogs and small fish ate insects — [[secondary consumers]]. Snakes and herons ate frogs — [[tertiary consumers]]. Each feeding step is a [[trophic level]]. Arranged in a line, they make a [[food chain]] — the [[grazing food chain]] (GFC) that starts with producers.', r:'The detritus food chain (DFC) begins with dead organic matter; in an aquatic ecosystem the GFC is the major conduit of energy flow.'},
  {t:'The Web Unravels', bg:'pond', e:'🕸️🐸➖', x:'Kiran drew arrows between all the animals. The chains crossed and joined into a [[food web]]. "Look — frogs ate insects and fed the snakes. Without frogs, insects multiplied and ate the plants, while snakes and herons went hungry." Removing one species had shaken the whole web. "Every organism depends on others," whispered the youngest Guardian.', r:'In a food web, energy flows along many interconnected food chains.'},
  {t:'The Clean-Up Crew', bg:'forest', e:'🪱🍂🍄', x:'At the muddy edge, earthworms, bacteria and fungi were at work — the [[decomposers]]. Kiran listed the steps of [[decomposition]]: [[fragmentation]] by detritivores, [[leaching]] of soluble nutrients, [[catabolism]] by enzymes, [[humification]] forming dark [[humus]], and [[mineralisation]] that releases nutrients back to the soil.', r:'Decomposition is faster when it is warm and moist, and slower in cold and dry conditions or without oxygen.'},
  {t:'Following the Energy', bg:'sky', e:'☀️⚡📉', x:'"All energy comes from the sun," said Kiran, "but plants capture only 2–10 percent of the [[photosynthetically active radiation]] (PAR)." Energy flows one way — [[unidirectional]] — from producers to consumers. At each step only about 10 percent passes on; the rest is lost as heat. This is the [[10 percent law]] of [[Lindeman]].', r:'PAR is about 50 percent of the incident solar radiation.'},
  {t:'Building Pyramids', bg:'lab', e:'🔺🔻📊', x:'The Guardians built [[ecological pyramids]] of number, biomass and energy. The pyramid of biomass in the sea is [[inverted]], because the small fish outweigh the phytoplankton at any moment. "But the [[pyramid of energy]] is always upright," said Kiran, "because energy is always lost at every level." The mass of living matter at each level is the [[standing crop]].', r:'Pyramids do not include saprophytes, even though they play a vital role in the ecosystem.'},
  {t:'The Frogs Return', bg:'pond', e:'🐸🌅🎉', x:'The Guardians cleaned the pond and stopped pesticides from draining into it. Slowly the frogs came back. Insects decreased, plants recovered, fish grew fat and herons returned. Nutrients cycled again through the decomposers. "Balance is restored," smiled Kiran. "An ecosystem is like a web of threads — pull one, and the whole web trembles."', r:'Ecosystem services such as pollination, purification of water and nutrient cycling are provided free by healthy ecosystems.'}],
 quiz:[['What is a producer?',['A plant-eating animal','Makes its own food by photosynthesis','A decomposer','A top predator'],1],['What happens if frogs are removed from the pond food web?',['Nothing changes','Insects increase; the web is unbalanced','All plants grow better','Energy flow increases'],1],['What is the role of decomposers?',['Make food from sunlight','Break down dead matter, return nutrients','Eat living plants','Produce oxygen'],1],['According to Lindeman, energy passed to the next trophic level is about:',['1%','10%','50%','90%'],1],['Which ecological pyramid is always upright?',['Number','Biomass','Energy','None'],2]]};

/* ================= Bonus books ================= */

BOOKS['bonus-division'] = { title:'The Copying Machine', ch:'Bonus · Cell Cycle and Cell Division', cover:'✂️', color:'#4a9d5b', page:'', bonus:1, star:'Cella the root-tip cell 🌱',
 pages:[
  {t:'An Urgent Message', bg:'field', e:'🌱📨🟢', x:'Deep in a growing root tip lived a young cell named Cella. One day an urgent message arrived: "Divide carefully. One mistake can change everything." Cella knew she was part of the [[cell cycle]] — the sequence by which a cell copies its DNA and divides into two. "A human cell takes about 24 hours," she remembered. "Yeast can do it in just 90 minutes!"', r:'The cell cycle has two phases: interphase (preparation) and the M phase (division).'},
  {t:'The Busy Rest', bg:'cell', e:'📚🧬⏳', x:'First came [[interphase]] — no rest at all! In the [[G1 phase]], Cella grew and made proteins. In the [[S phase]] she copied her DNA, so the amount doubled from 2C to 4C — but the [[chromosome number]] stayed the same. In the [[G2 phase]] she made proteins for division. Some cells stop dividing and enter a quiet [[G0 phase]].', r:'Interphase takes more than 95 percent of the cell cycle. In animal cells the centriole also duplicates in the S phase.'},
  {t:'Prophase: Packing Up', bg:'cell', e:'🧶➡️🧬', x:'The M phase began with [[prophase]]. Cella’s long chromatin threads coiled and condensed into visible [[chromosomes]], each made of two [[sister chromatids]] joined at the [[centromere]]. The spindle began to form. Slowly the Golgi complex, ER, [[nucleolus]] and [[nuclear envelope]] disappeared from view.', r:'Mitosis is called equational division because the chromosome number of the daughter cells equals that of the parent.'},
  {t:'Metaphase: Line Up!', bg:'lab', e:'📏🧬🧬', x:'In [[metaphase]], [[spindle fibres]] attached to disc-shaped [[kinetochores]] on each centromere. The chromosomes moved and lined up neatly along the middle of the cell — the [[metaphase plate]]. "This is the best stage to study the shape of chromosomes," whispered a microscope from above.', r:'Metaphase is identified by all chromosomes lying at the equator, each attached to spindle fibres from both poles.'},
  {t:'Anaphase: Pull Apart', bg:'cell', e:'↔️🧬🧬', x:'In [[anaphase]], each centromere split. The [[sister chromatids]] — now called daughter chromosomes — were pulled to opposite poles by the shortening spindle fibres, centromere first. "Exactly one copy to each side," counted Cella. "No mistakes allowed!"', r:'At anaphase, centromeres split and chromatids separate; chromatids move to opposite poles.'},
  {t:'Telophase and the Split', bg:'garden', e:'🟢🟢🧱', x:'In [[telophase]], the chromosomes reached the poles and uncoiled. Nuclear envelopes and nucleoli formed again — two new nuclei! Then came [[cytokinesis]]. "Animal cells pinch in with a furrow," said Cella, "but I am a plant cell with a rigid wall." A [[cell plate]] grew from the centre outward and became the new wall.', r:'Karyokinesis without cytokinesis forms a multinucleate syncytium, e.g. the liquid endosperm of coconut.'},
  {t:'When Copying Goes Wrong', bg:'night', e:'⚠️🧬❌', x:'Cella remembered her teacher’s warning. If DNA is copied with an error, the change is a [[mutation]]. If cells divide out of control, a [[tumour]] can form. "That is why there are checkpoints in the cycle," she said. Mitosis is important for [[growth]], for [[repair]] of tissues and for keeping the right [[nucleo-cytoplasmic ratio]].', r:'Meristems (apical and lateral) of plants divide continuously by mitosis and cause growth throughout life.'},
  {t:'Two Healthy Cells', bg:'field', e:'🟢🟢🎉', x:'Cella was now two healthy, identical [[daughter cells]], each with the same number of chromosomes. Far away, in a flower’s anther, a different division was happening — [[meiosis]], which halves the chromosome number to make gametes and mixes genes by [[crossing over]]. "Both divisions keep life going," Cella smiled, as the root tip grew a little deeper.', r:'Meiosis: one DNA replication and two divisions give four haploid cells. Crossing over occurs at pachytene of prophase I.'}],
 quiz:[['During which phase does DNA replicate?',['G1 phase','S phase','G2 phase','M phase'],1],['What separates during anaphase of mitosis?',['Homologous chromosomes','Sister chromatids','Nuclear envelopes','Cell walls'],1],['What is the result of mitosis?',['Four haploid cells','Two genetically identical cells','One large cell','Gametes only'],1],['Chromosomes line up at the equator during:',['Prophase','Metaphase','Anaphase','Telophase'],1],['In plant cells, cytokinesis takes place by:',['Furrow formation','Cell plate formation','Budding','Fission'],1]]};

BOOKS['bonus-photo'] = { title:'The Sunlight Factory', ch:'Bonus · Photosynthesis in Higher Plants', cover:'🏭', color:'#3f9e3f', page:'', bonus:1, star:'Chloro the leaf factory 🏭',
 pages:[
  {t:'The Factory Is Failing', bg:'garden', e:'🏭🍂⚠️', x:'In a green leaf, a tiny factory named Chloro was running out of power. "My machines need three things: [[sunlight]], [[water]] and [[carbon dioxide]]. Without them the whole plant will starve!" Chloro’s job is [[photosynthesis]]: 6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O, using light energy. Students, you must help collect the ingredients!', r:'Photosynthesis is the basis of life on Earth: it gives us food and releases oxygen into the atmosphere.'},
  {t:'Gates and Pipes', bg:'field', e:'🚪💨💧', x:'First, carbon dioxide entered through tiny pores on the leaf called [[stomata]]. Water climbed all the way from the roots through the [[xylem]]. Long ago [[Joseph Priestley]] showed that a plant could restore air ‘spoiled’ by a burning candle, and [[Jan Ingenhousz]] showed that this happened only in sunlight. Later it was proved that the oxygen released comes from [[water]], not from CO₂.', r:'Cornelius van Niel showed that hydrogen from water reduces CO₂ to carbohydrate; oxygen comes from water.'},
  {t:'The Solar Panels', bg:'cell', e:'🟢☀️🔆', x:'Inside the [[chloroplast]], stacks of [[thylakoids]] called grana held the solar panels — pigments. [[Chlorophyll a]], the chief pigment, absorbs mainly blue and red light. [[Chlorophyll b]], [[xanthophylls]] and [[carotenoids]] are [[accessory pigments]] that widen the range of light used and protect chlorophyll a. Pigments are grouped in [[light harvesting complexes]] around a reaction centre.', r:'PS I has the reaction centre P700 and PS II has P680, named after the wavelengths they absorb best.'},
  {t:'The Light Reaction', bg:'sky', e:'⚡💧🫧', x:'When light struck [[PS II]], electrons were boosted to a high energy level. To replace them, water was split — [[photolysis]] — releasing oxygen bubbles. Electrons flowed along the [[Z scheme]] to [[PS I]] and finally reduced NADP⁺ to [[NADPH]]. Protons built up inside the thylakoid and flowed out through ATP synthase to make [[ATP]] — [[chemiosmosis]].', r:'Making ATP using light is photophosphorylation; cyclic photophosphorylation uses only PS I and makes no NADPH or O₂.'},
  {t:'The Sugar Kitchen', bg:'cell', e:'🍬🔄🧪', x:'ATP and NADPH carried energy to the [[stroma]], where the [[Calvin cycle]] ran. The enzyme [[RuBisCO]] joined CO₂ to [[RuBP]] — [[carboxylation]] — making two molecules of [[3-PGA]], the first stable product. So these plants are called [[C₃ plants]]. Next came reduction to sugar and regeneration of RuBP.', r:'To make one glucose molecule the Calvin cycle turns 6 times, using 18 ATP and 12 NADPH.'},
  {t:'The C₄ Shortcut', bg:'field', e:'🌽☀️🔥', x:'In a hot maize field, Chloro met a cousin. "We are [[C₄ plants]] like maize and sugarcane. Our first product is the four-carbon [[oxaloacetic acid]]." In the mesophyll, [[PEP carboxylase]] fixes CO₂; then the Calvin cycle runs inside large [[bundle sheath cells]] arranged in a wreath — [[Kranz anatomy]]. "We do not suffer from photorespiration!"', r:'C₄ plants tolerate high temperatures, show higher productivity and respond to high light intensities.'},
  {t:'A Wasteful Mistake', bg:'desert', e:'🌡️😵🔀', x:'On hot, bright days RuBisCO sometimes grabbed O₂ instead of CO₂ — [[photorespiration]]. No sugar or ATP was made; energy was wasted. Chloro also learnt [[Blackman’s law of limiting factors]]: when many factors affect a process, the rate is set by the one in shortest supply — light, [[CO₂ concentration]], [[temperature]] or water.', r:'CO₂ is the major limiting factor; tomato and bell pepper greenhouses are enriched with CO₂ for higher yields.'},
  {t:'Glucose and Oxygen', bg:'garden', e:'🍬🫧🌿', x:'With sunlight, water and CO₂ flowing in, Chloro’s machines hummed. [[Glucose]] was made for food and stored as starch, and [[oxygen]] bubbled out of the stomata for every animal to breathe. The plant grew strong and green again. "Every bite you eat," said Chloro proudly, "began as sunlight caught in a leaf."', r:'Products of photosynthesis: glucose (carbohydrate) and oxygen; water is also formed.'}],
 quiz:[['What gas do plants take in for photosynthesis?',['Oxygen','Carbon dioxide','Nitrogen','Hydrogen'],1],['Which pigment is chiefly responsible for absorbing sunlight?',['Chlorophyll a','Xanthophyll','Haemoglobin','Carotene'],0],['What are the products of photosynthesis?',['CO₂ and water','Glucose and oxygen','ATP only','Starch and CO₂'],1],['The first stable product of the Calvin cycle is:',['Oxaloacetic acid','3-PGA','RuBP','Glucose'],1],['The oxygen released in photosynthesis comes from:',['CO₂','Water','Glucose','Air'],1]]};

BOOKS['bonus-resp'] = { title:'Energy from Food', ch:'Bonus · Respiration (Cellular Energy)', cover:'🏃', color:'#e07a3a', page:'', bonus:1, star:'Aarav 🏃 & Glucose 🍬',
 pages:[
  {t:'Race Day', bg:'field', e:'🏃🏁🍬', x:'Aarav stood at the starting line of the school race. "Where will my muscles get their energy?" he wondered. Inside his cells, [[glucose]] from breakfast and [[oxygen]] from the air were about to begin a journey called [[cellular respiration]]: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + energy. The energy is stored in [[ATP]], the cell’s energy currency.', r:'Respiration is the breaking of C–C bonds of food by oxidation inside cells to release energy, trapped as ATP.'},
  {t:'Splitting the Sugar', bg:'cell', e:'🍬✂️🔸', x:'The journey began in the [[cytoplasm]] with [[glycolysis]], also called the [[EMP pathway]] after Embden, Meyerhof and Parnas. One glucose (6C) was split into two molecules of [[pyruvic acid]] (3C). "No oxygen needed yet," said Glucose. The net gain was 2 ATP and 2 NADH.', r:'Glycolysis occurs in all living organisms; the fate of pyruvic acid depends on whether oxygen is available.'},
  {t:'Into the Powerhouse', bg:'cell', e:'🔋🚪🔸', x:'With oxygen around, pyruvic acid entered the [[mitochondria]]. In the [[matrix]], the enzyme [[pyruvate dehydrogenase]] converted it into [[acetyl CoA]], releasing CO₂ and making NADH. This link step connects glycolysis to the next big wheel of energy.', r:'Aerobic respiration takes place in the mitochondria and needs oxygen.'},
  {t:'The Krebs Wheel', bg:'lab', e:'🎡🔁⚡', x:'Acetyl CoA joined [[oxaloacetic acid]] to form [[citric acid]], starting the [[Krebs cycle]], discovered by [[Hans Krebs]]. As the wheel turned, CO₂ was released and the energy carriers [[NADH]] and [[FADH₂]] were filled up, along with one GTP. "The real energy cash is still waiting," said Glucose.', r:'For each pyruvate, the Krebs cycle gives 3 NADH, 1 FADH₂ and 1 ATP (GTP), releasing 2 CO₂.'},
  {t:'The Electron Waterfall', bg:'cell', e:'⬇️⚡💧', x:'NADH and FADH₂ handed their electrons to the [[electron transport system]] (ETS) in the [[inner mitochondrial membrane]]. Electrons flowed down like a waterfall, and [[oxygen]] waited at the bottom as the [[final electron acceptor]], forming water. The energy drove [[ATP synthase]] (F₀–F₁) to make ATP — [[oxidative phosphorylation]].', r:'One NADH gives about 3 ATP and one FADH₂ about 2 ATP; aerobic respiration yields a net of up to 38 ATP per glucose.'},
  {t:'The Final Sprint', bg:'field', e:'🏃💨😮‍💨', x:'In the last 100 metres, Aarav’s muscles needed energy faster than oxygen could arrive. So they switched to [[anaerobic respiration]]: pyruvic acid became [[lactic acid]] with the help of lactate dehydrogenase. Only 2 ATP per glucose — and the lactic acid made his legs ache with [[fatigue]]. Yeast does something similar, making [[ethanol]] and CO₂ — [[alcoholic fermentation]].', r:'Fermentation releases less than 7 percent of the energy in glucose.'},
  {t:'The Respiratory Quotient', bg:'lab', e:'⚗️📊🥜', x:'After the race, Aarav’s teacher showed him the [[respiratory quotient]] (RQ) = volume of CO₂ released ÷ volume of O₂ used. "For carbohydrates RQ is 1. For fats it is less than 1 — about 0.7 for tripalmitin. For proteins it is about 0.9." Because respiration both breaks down and builds molecules, it is called an [[amphibolic pathway]].', r:'Fats enter respiration as glycerol and fatty acids; proteins enter as amino acids after deamination.'},
  {t:'Across the Finish Line', bg:'sky', e:'🏁🥇🎉', x:'Aarav crossed the finish line first! His cells had made enough ATP to power every stride. As he breathed deeply, oxygen rushed back to clear the lactic acid. "So that is why we breathe," he laughed. "Food gives the fuel, oxygen burns it, and mitochondria turn it into ATP!"', r:'Aerobic respiration products: CO₂, water and energy (ATP).'}],
 quiz:[['Which organelle carries out aerobic respiration?',['Chloroplast','Mitochondrion','Nucleus','Ribosome'],1],['What are the products of aerobic respiration?',['Glucose and oxygen','CO₂, water and ATP','Lactic acid only','Ethanol and CO₂'],1],['Why do muscles produce lactic acid during intense exercise?',['Too much oxygen','Shortage of oxygen leads to anaerobic respiration','They make more glucose','They stop respiring'],1],['Glycolysis takes place in the:',['Mitochondrial matrix','Cytoplasm','Nucleus','Inner membrane'],1],['The final electron acceptor in aerobic respiration is:',['NAD⁺','Oxygen','CO₂','Pyruvate'],1]]};

BOOKS['bonus-body'] = { title:'The Body Rescue Mission', ch:'Bonus · Human Physiology', cover:'🚑', color:'#d0563e', page:'', bonus:1, star:'The Micro-Medics 🧑‍⚕️',
 pages:[
  {t:'Alarm in the Body', bg:'city', e:'🚨🧑‍⚕️🚑', x:'An alarm blared inside a human body: "Energy levels low. Oxygen delivery weak!" A team of tiny medical explorers, the Micro-Medics, shrank into a capsule and set off. "Our mission," said their leader, Dr. Asha, "is to check five [[organ systems]]: circulatory, respiratory, digestive, nervous and excretory. Every one must work together."', r:'Organs that work together for a common function form an organ system.'},
  {t:'Stop 1: The Heart', bg:'city', e:'❤️🔁🩸', x:'The capsule rode the bloodstream into the [[heart]], with four chambers: two [[atria]] and two [[ventricles]]. The [[SA node]], the [[pacemaker]], fired about 72 times a minute. "Blood passes through the heart twice in one round — [[double circulation]]," said Dr. Asha. Each beat pushed about 70 mL — the [[stroke volume]].', r:'Cardiac output = stroke volume × heart rate ≈ 5 litres per minute. One cardiac cycle lasts about 0.8 s.'},
  {t:'Stop 2: The Lungs', bg:'sky', e:'🫁💨🫧', x:'Next were the [[lungs]], branching into millions of tiny air sacs, the [[alveoli]] — the site of [[gas exchange]]. Oxygen diffused into the blood and joined [[haemoglobin]] in red blood cells as [[oxyhaemoglobin]]. CO₂ moved out, mostly carried as [[bicarbonate]]. Breathing rhythm is set by the [[respiratory rhythm centre]] in the [[medulla]].', r:'About 97 percent of O₂ is carried by RBCs; about 70 percent of CO₂ is carried as bicarbonate.'},
  {t:'Stop 3: The Stomach', bg:'desert', e:'🍽️🧪🔥', x:'In the [[stomach]], [[gastric glands]] poured out [[hydrochloric acid]] and [[pepsinogen]]. The acid converted pepsinogen into [[pepsin]], which began digesting proteins. Earlier, in the mouth, [[salivary amylase]] had started breaking starch. "Food here becomes an acidic paste called [[chyme]]," Dr. Asha explained.', r:'Mucus and bicarbonates protect the stomach lining from HCl.'},
  {t:'Stop 4: The Intestine', bg:'river', e:'🌀🟡🍃', x:'In the [[small intestine]], [[bile]] from the liver [[emulsified]] fats into tiny droplets, and [[pancreatic juice]] brought trypsin, amylase and lipase. Finger-like [[villi]] covered the walls, giving a huge surface for [[absorption]]. Simple sugars, amino acids and fatty acids passed into the blood and lymph. Nutrients were on their way to every cell!', r:'Most digestion and absorption happen in the small intestine; water is mainly absorbed in the large intestine.'},
  {t:'Stop 5: The Brain', bg:'night', e:'🧠⚡📡', x:'The capsule zipped up to the [[brain]], the control centre. Billions of [[neurons]] sent electrical [[nerve impulses]], passing messages across gaps called [[synapses]] using [[neurotransmitters]]. The [[cerebrum]] handled thinking, the [[cerebellum]] kept balance, and the [[medulla]] controlled breathing and heartbeat.', r:'The resting membrane of a neuron is negative inside; an impulse is a wave of depolarisation.'},
  {t:'Stop 6: The Kidneys', bg:'river', e:'🫘💧🚽', x:'Finally they reached the [[kidneys]], each with about a million [[nephrons]]. In the [[glomerulus]], blood was filtered — [[glomerular filtration]] — about 125 mL per minute, or 180 litres a day! Nearly 99 percent was taken back by [[reabsorption]]. Waste [[urea]] left as urine. [[ADH]] helped save water when the body was thirsty.', r:'Kidneys are the main organs of excretion; urea is formed in the liver.'},
  {t:'All Systems Go!', bg:'sky', e:'✅❤️🫁', x:'With every system checked, oxygen reached the cells, nutrients were absorbed, messages flowed and waste was removed. The alarm turned green: "Body at full health." Dr. Asha smiled. "No system works alone. The heart needs the lungs, the cells need the gut, and the kidneys keep the blood clean. Mission complete!"', r:'Coordination between organ systems keeps the internal environment stable — homeostasis.'}],
 quiz:[['Which system transports oxygen and nutrients?',['Digestive','Circulatory','Excretory','Nervous'],1],['Where does gas exchange occur in the lungs?',['Trachea','Bronchi','Alveoli','Diaphragm'],2],['Which organ filters waste from the blood?',['Liver','Kidney','Stomach','Heart'],1],['The pacemaker of the heart is the:',['AV node','SA node','Bundle of His','Medulla'],1],['Fats are emulsified by:',['Pepsin','Bile','Saliva','HCl'],1]]};
